    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "START / IDLE",
      "entry": "Initial state or pallet cleared at DONE (LDF X23 / ANI X23 resets M207 and M200)",
      "exit": "Pallet arrives in test position (LDP X23) with cell in auto (X2), no active ST20 fault (ANI M299), and station idle (ANI M200)"
    },
    {
      "name": "CLAMP (M201)",
      "entry": "Start conditions met; sets M200 (busy) and M201 (clamp step)",
      "exit": "Clamp confirmed closed (X20) and not open (ANI X21)"
    },
    {
      "name": "FILL (M202)",
      "entry": "Clamp confirmed closed from M201",
      "exit": "Pressure reaches fill threshold PT-2001 >= 14.50 kPa (D100 >= D122) or aborts on fill timeout (T21) / active fault (M299)"
    },
    {
      "name": "STABILISE (M203)",
      "entry": "Fill complete condition met (D100 >= D122)",
      "exit": "Stabilisation timer completes (T22 done)"
    },
    {
      "name": "TEST (M204)",
      "entry": "Stabilisation timer T22 completes",
      "exit": "Test window timer completes (T23 done)"
    },
    {
      "name": "VENT (M205)",
      "entry": "Test window complete (T23 done), or fault abort while busy (M299 AND M200)",
      "exit": "Vent timer complete (T200 / T24 done), pressure vented below 1.00 kPa (D100 < K100), and PT-2001 signal healthy (ANI M292)"
    },
    {
      "name": "UNCLAMP (M206)",
      "entry": "Vent conditions satisfied from M205",
      "exit": "Clamp confirmed open (X21) and clamp closed switch clear (ANI X20)"
    },
    {
      "name": "DONE / RESULT (M207)",
      "entry": "Clamp confirmed open from M206",
      "exit": "Pallet departs test position (ANI X23)"
    }
  ],
  "interlocks": [
    {
      "cause": "Pallet sensor (X23) drops and returns while test is running (M200 ON)",
      "effect": "Cycle restart is inhibited (ANI M200 in start rung R8)"
    },
    {
      "cause": "Clamp confirmed closed lost (loss of X20 / clamp not closed in step M202)",
      "effect": "Fill valve (XV-2003 / Y21) cannot open / closes immediately (driven only in M202)"
    },
    {
      "cause": "ST20 fault active (M299)",
      "effect": "Fill valve XV-2003 (Y21) forced closed; active cycle aborts to VENT (M205) with FAIL result (M211)"
    },
    {
      "cause": "Overpressure detected (PT-2001 > 20.00 kPa / M291)",
      "effect": "Fill valve closed; vent valve XV-2004 (Y22) held open; fault beacon Y25 energized"
    },
    {
      "cause": "Vent incomplete (pressure >= 1.00 kPa or vent timer running) or PT-2001 fault active (M292)",
      "effect": "Unclamp is inhibited; station holds in VENT step (M205) with vent valve open"
    },
    {
      "cause": "Manual vent pushbutton PB-2010 (X25) pressed while in manual mode (ANI X2)",
      "effect": "Vent valve XV-2004 (Y22) opens manually"
    },
    {
      "cause": "E-stop chain not healthy (ES-0001 / X0 OFF)",
      "effect": "ST20 fault flag M299 turns ON, aborting cycle to VENT with FAIL result"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test pressure not reached within fill timeout period (T21 expires while in FILL M202)",
      "action": "Latches M290; triggers ST20 fault M299, aborts cycle to VENT (M205), and sets FAIL (M211)"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 pressure exceeds 20.00 kPa (D100 > D123)",
      "action": "Sets latched alarm M291; triggers ST20 fault M299, forces fill valve closed, holds vent valve Y22 open, sets FAIL"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading below -5.00 kPa (D100 < K-500, indicating wire break)",
      "action": "Turns on unlatched alarm M292; triggers M299 (inhibits cycle start) and blocks unclamp transition out of VENT (R22)"
    },
    {
      "name": "Supply air low",
      "condition": "Supply air switch PS-2009 lost while station busy (M200 AND ANI X22)",
      "action": "Sets latched alarm M293; triggers ST20 fault M299, aborts cycle to VENT, sets FAIL"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (section 4.4)",
      "parameter_sheet_says": "5.0 s (T22, changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (R13 uses OUT T22 K50, where 100 ms * K50 = 5.0 s)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (section 4.7)",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21 uses OUT T200 K50 on FX5U 100 ms timer base, instead of 0.5 s / T24)",
      "authoritative": "parameter_sheet"
    }
  ]
}
